func TestDryRunReportAccountsForCoveredSessions(t *testing.T) {
	now := time.Date(2026, 11, 10, 12, 0, 0, 0, time.UTC)
	brainDir := writeOrderedDistillFixture(t, now, "old", "mid", "new")
